using System;using System.Collections.Generic;using UnityEngine;
public partial class DungeonPrototype {
 CityNoticeRule PendingCityNotice(string locationId){if(City==null||City.story==null)return null;CityNoticeSystem.Normalize(cityProgress);return Array.Find(City.story.notices,r=>r!=null&&r.locationId==locationId&&CityNoticeSystem.Available(r,cityProgress,CityMenuLocations));}
 bool PlayCityNotice(string locationId){var notice=PendingCityNotice(locationId);if(notice==null)return false;worldDialogue.Begin(notice.dialogue,()=>CityNoticeSystem.Read(notice,cityProgress));return true;}
 void MarkCityVisited(string id){CityNoticeSystem.Normalize(cityProgress);if(!string.IsNullOrEmpty(id)&&!cityProgress.visitedLocations.Contains(id))cityProgress.visitedLocations.Add(id);}
 List<CityDungeonDestination> CityDungeonDestinations(){CityNoticeSystem.Normalize(cityProgress);var result=new List<CityDungeonDestination>();if(City.story!=null)foreach(var destination in City.story.destinations)if(destination!=null&&destination.map!=null&&!string.IsNullOrEmpty(destination.scenePath)&&(string.IsNullOrEmpty(destination.requiredFlag)||cityProgress.storyFlags.Contains(destination.requiredFlag)))result.Add(destination);return result;}
 string[] CityDungeonServices(){var labels=new List<string>();foreach(var destination in CityDungeonDestinations())labels.Add(City.story.travelPrefix+destination.displayName);if(labels.Count==0)labels.Add(City.story!=null?City.story.guideQuestion:"Hablar con el guía");labels.Add(City.texts.back);return labels.ToArray();}
 void ExecuteCityDungeonService(int index){var destinations=CityDungeonDestinations();if(destinations.Count==0){if(City.story!=null)worldDialogue.Begin(City.story.noDestinationDialogue);return;}if(index<0||index>=destinations.Count)return;var target=destinations[index];var source=CaptureCityModelSave();bool first;var data=DungeonMapPersistence.ForTravel(source,target.map,target.map.startCell,target.map.startHeading,out first);data.city.inCity=false;data.city.locationId="";data.introductionCompleted=true;DigitalKingdomTransit.Explore(data,target.map,target.scenePath,City,first);}
 public bool CanReturnToKingdom {get{if(cityDataOnly||battle||lost||City==null||City.story==null||!cityProgress.discovered)return false;return Array.Exists(City.story.destinations,d=>d!=null&&d.map==ActiveMap&&d.map!=DungeonMapSettings.Current);}}
 public bool ReturnFromKingdomDungeon(){if(!CanReturnToKingdom||moving||worldDialogue.Active||DungeonWhiteTransition.Active)return false;var source=CaptureDungeonSave();var originalMap=DungeonMapPersistence.Resolve(cityProgress.returnMapId);if(originalMap==null)return false;bool first;var data=DungeonMapPersistence.ForTravel(source,originalMap,cityProgress.returnCell,cityProgress.returnHeading,out first);data.city.inCity=true;data.city.locationId="";DigitalKingdomTransit.Enter(data,originalMap,City.scenePath,City);return true;}
 bool TryLoadKingdomFloor(DungeonMapSettings destination,DungeonSaveData data,bool firstVisit){if(City==null||City.story==null)return false;var route=Array.Find(City.story.destinations,r=>r!=null&&r.map==destination);if(route!=null){DigitalKingdomTransit.Explore(data,destination,route.scenePath,City,firstVisit);return true;}if(GetComponent<RetroDungeonWallComposer>()!=null){DigitalKingdomTransit.Explore(data,destination,City.fallbackDungeonScene,City,firstVisit);return true;}return false;}
 public bool ReturnFromKingdomDoor(){if(battle||lost||moving||worldDialogue.Active||DungeonWhiteTransition.Active)return false;if(!cityProgress.discovered){var main=DungeonMapSettings.Current;cityProgress.discovered=true;cityProgress.returnMapId=main.mapId;cityProgress.returnMap=main.name;cityProgress.returnScene=City.fallbackDungeonScene;cityProgress.returnCell=main.startCell;cityProgress.returnHeading=main.startHeading;}return ReturnFromKingdomDungeon();}
 string[] PauseMainOptions(){return CanReturnToKingdom?new[]{"PERSONAJE","INVENTARIO","MAPA","AJUSTES","VOLVER A DIGITAL KINGDOM","CERRAR MENÚ"}:new[]{"PERSONAJE","INVENTARIO","MAPA","AJUSTES","CERRAR MENÚ"};}
}
